        rgb_image = np.array([[[255, 0, 0], [0, 255, 0]], [[0, 0, 255], [128, 128, 128]]], dtype=np.uint8)
        expected_gray = np.dot(rgb_image, [0.299, 0.587, 0.114]).astype(np.uint8)
        gray_image = grayscale(rgb_image)
        assert np.array_equal(gray_image, expected_gray)

